 * applyRate(cents, rateBp, mode): cents × rateBp / 10000 (rateBp em pontos-base,
 * 1 bp = 0,01%), arredondado com divRound. Produto fora do intervalo seguro → RangeError.
 */
export function applyRate(cents, rateBp, mode = 'half-even') {
